const taskId = $json.task_id;
const stepNo = $json.step_no;
const rawStatus = ($json.status || 'info').toLowerCase();
const message = $json.message || '';
const pr = $json.pr_url || '';
const branch = $json.branch || '';
const commit = $json.commit || '';
const changedFiles = $json.changed_files || '';
const startedAt = $json.started_at ? new Date($json.started_at) : null;
const finishedAt = $json.finished_at ? new Date($json.finished_at) : null;

const emojiMap = { success: '✅', failed: '❌', info: 'ℹ️', warning: '⚠️' };
const emoji = emojiMap[rawStatus] || 'ℹ️';
const status = rawStatus.toUpperCase();

let elapsed = '';
if (startedAt && finishedAt && !Number.isNaN(startedAt.getTime()) && !Number.isNaN(finishedAt.getTime())) {
  const seconds = Math.max(0, Math.round((finishedAt.getTime() - startedAt.getTime()) / 1000));
  elapsed = `${seconds}s`;
}

const lines = [
  `${emoji} Task #${taskId} | Step ${stepNo} | ${status}`,
  message
];
if (elapsed) lines.push(`Time: ${elapsed}`);
if (branch) lines.push(`Branch: ${branch}`);
if (commit) lines.push(`Commit: ${commit}`);
if (changedFiles) lines.push(`Files: ${changedFiles}`);
if (pr) lines.push(`PR: ${pr}`);

return [{ text: lines.filter(Boolean).join('\n') }];
